const quote_id='P02-Q-DEMO-PREVIEW';
const lines=['# DEMO Contract Preview','Reference: '+quote_id,'Service: AI Automation','Indicative fee: USD 650.00','External signature must be verified before invoice issue.'];
return {json:{demo_only:true,quote_id,contract_id:'CON-'+quote_id,invoice_id:'INV-'+quote_id,contract_status:'preview_only',invoice_status:'preview_only',subtotal_usd:650,tax_usd:null,total_due_usd:null,contract_markdown:lines.join('

'),invoice_markdown:'# DEMO Invoice Preview
Subtotal: USD 650.00
Tax: Pending finance review
Total due: Not issued',message:'No rows were created by this preview.'}};

const q=$('PrepareDocumentRequest').first().json.quote_id;
const opp=$('GetApprovedOpportunity').first().json||{};
const prop=$('GetApprovedProposal').first().json||{};
const reasons=[];
if(opp.quote_id!==q||prop.quote_id!==q)reasons.push('Quote not found in both proposal and pipeline');
if(opp.approval_status!=='approved'||prop.approval_status!=='approved')reasons.push('Human sales approval is required');
if(opp.lead_id!==prop.lead_id)reasons.push('Lead reference mismatch');
const fee=Number(prop.indicative_subtotal_usd);
if(!Number.isFinite(fee)||fee<=0)reasons.push('Invalid approved subtotal');
let quotation={};
try{quotation=JSON.parse(prop.quotation_json||'{}');}catch{reasons.push('Quote JSON invalid');}
if(quotation.currency&&quotation.currency!=='USD')reasons.push('Only USD is supported in this demo');
if(quotation.indicative_subtotal!==null && quotation.indicative_subtotal!==undefined && Math.abs(Number(quotation.indicative_subtotal)-fee)>0.009)reasons.push('Quote subtotal mismatch');
if(!String(prop.proposal_markdown||'').trim())reasons.push('Proposal text missing');
return {json:{allowed:reasons.length===0,reason:reasons.join('; '),quote_id:q,lead_id:prop.lead_id||'',company:prop.company||'',service_needed:prop.service_needed||'',currency:'USD',service_fee_usd:fee,proposal_markdown:prop.proposal_markdown||'',quotation}};

const d=$('EvaluateDocumentEligibility').first().json;
const now=new Date().toISOString();
const fee=Number(d.service_fee_usd).toFixed(2);
const contract_id='CON-'+d.quote_id;
const invoice_id='INV-'+d.quote_id;
const safe=v=>String(v??'').replace(//g,'').trim();
const contract=`# DRAFT Services Agreement (NOT SIGNED)

Contract ID: ${contract_id}
Quote ID: ${d.quote_id}
Customer: ${safe(d.company)}
Service category: ${safe(d.service_needed)}

## Proposed scope (subject to final legal review)
${safe(d.proposal_markdown)}

## Pricing
Indicative approved service subtotal: USD ${fee}
Taxes, final terms, payment milestones and third-party costs require finance/legal confirmation.

## Signature and acceptance
Not signed. This draft must be independently reviewed, accepted and signed using an external process.

No obligation or invoice is created by this draft.`;
const invoice=`# DRAFT Invoice (NOT ISSUED)

Invoice ID: ${invoice_id}
Contract ID: ${contract_id}
Customer: ${safe(d.company)}
Service: ${safe(d.service_needed)}
Currency: USD
Subtotal: USD ${fee}
Tax: Not determined
Final amount due: Not determined
Issue date: Not issued
Due date: Not determined

Do not send or request payment. Await documented contract signature and authorized finance release.`;
return {json:{contract_id,invoice_id,quote_id:d.quote_id,lead_id:d.lead_id,company:d.company,service_needed:d.service_needed,currency:'USD',service_fee_usd:d.service_fee_usd,subtotal_usd:d.service_fee_usd,tax_usd:null,total_due_usd:null,paid_amount_usd:0,contract_markdown:contract,invoice_markdown:invoice,contract_status:'draft_pending_signature',invoice_status:'draft_pending_review',signature_evidence_ref:'',reviewed_by:'',reviewed_at:'',issue_date:'',due_date:'',released_by:'',released_at:'',paid_at:'',created_at:now}};

const v=$json, s=x=>String(x??'').trim();
const invoice_id=s(v.invoice_id), reviewer=s(v.reviewer), evidence=s(v.signature_evidence_ref);
const taxStr=s(v.tax_usd), tax=Number(taxStr); const date=s(v.due_date);
const valid=invoice_id.length>5&&reviewer.length>1&&evidence.length>3&&s(v.signature_verified)==='Yes'&&taxStr!==''&&Number.isFinite(tax)&&tax>=0&&Math.abs(tax*100-Math.round(tax*100))<1e-6&&(/^\d{4}-\d{2}-\d{2}$/.test(date) && !Number.isNaN(Date.parse(date+'T00:00:00Z')) && new Date(date+'T00:00:00Z').toISOString().slice(0,10)===date);
return {json:{valid,invoice_id,reviewer,signature_evidence_ref:evidence,tax_usd:tax,due_date:date,review_notes:s(v.review_notes),reason:valid?'':'Invoice ID, reviewer, signed-contract evidence, verified tax (2 decimals), and due date are required.'}};

const r=$('PrepareFinanceReview').first().json;
const invoice=$('LoadInvoiceForRelease').first().json||{};
const contract=$('LoadContractForRelease').first().json||{};
const opp=$('LoadOpportunityForRelease').first().json||{};
const reasons=[];
if(invoice.invoice_id!==r.invoice_id)reasons.push('Invoice not found');
if(invoice.invoice_status!=='draft_pending_review')reasons.push('Invoice is not a draft pending review');
if(contract.contract_id!==invoice.contract_id||contract.quote_id!==invoice.quote_id)reasons.push('Linked contract not found');
if(!['draft_pending_signature','signature_verified_by_reviewer'].includes(contract.contract_status))reasons.push('Contract not eligible for release');
if(contract.contract_status==='signature_verified_by_reviewer' && contract.signature_evidence_ref && contract.signature_evidence_ref!==r.signature_evidence_ref)reasons.push('Stored signature evidence differs; manual review required');
if(opp.quote_id!==invoice.quote_id||opp.approval_status!=='approved')reasons.push('Sales approval missing');
if(!Number.isFinite(Number(invoice.subtotal_usd))||Number(invoice.subtotal_usd)<=0)reasons.push('Subtotal invalid');
const today=new Date().toISOString().slice(0,10);
if(r.due_date<today)reasons.push('Due date must not be before today');
const total=Math.round((Number(invoice.subtotal_usd)+r.tax_usd)*100)/100;
if(total<=0)reasons.push('Final total invalid');
const issuedAt=new Date().toISOString();
const md=`# Issued Invoice Record\n\nInvoice ID: ${invoice.invoice_id}\nContract ID: ${invoice.contract_id}\nCustomer: ${invoice.company}\nCurrency: USD\nSubtotal: USD ${Number(invoice.subtotal_usd).toFixed(2)}\nReviewed tax: USD ${r.tax_usd.toFixed(2)}\n**Total Due: USD ${total.toFixed(2)}**\nIssue Date: ${today}\nDue Date: ${r.due_date}\nFinance Reviewer: ${r.reviewer}\nExternal signed-contract evidence reference: ${r.signature_evidence_ref}\n\nThis is a system record, not proof of payment or of an independently verified signature.`;
return {json:{...r,allowed:reasons.length===0,reason:reasons.join('; '),contract_id:invoice.contract_id,quote_id:invoice.quote_id,reviewed_at:issuedAt,issue_date:today,total_due_usd:total,invoice_markdown:md,invoice_status:'issued',contract_status:'signature_verified_by_reviewer'}};
